setp_start_template = '''
#### SETP SCRIPT BEGIN #######
'''
setp_end_template = '''
#### SETP SCRIPT END #######
'''
script_template = "SETP {flag_name} {value}\n"


class SETPScript(object):
    """
    SETP command script generator
    """

    def __init__(self, flags):
        self.flags = flags

    def __str__(self):
        final_script = ''
        for key in self.flags:
            final_script += script_template.format(flag_name=key, value=self.flags[key])
        return setp_start_template + final_script + setp_end_template

    def __add__(self, other):
        return str(self) + str(other)

    def __radd__(self, other):
        return str(other) + str(self)
